interface MangaDetail {
  title: string;
  volumes: Volume[];
  author: string;
  publisher: string;
  magazine: string;
  demographic: string;
  genres: string[];
  startDate: string;
}

interface RankingData {
  title: string;
  [key: string]: string | number;
}

const DetailPage: React.FC = () => {
  const [searchParams] = useSearchParams();
  const [mangaDetail, setMangaDetail] = useState<MangaDetail | null>(null);
  const [rankingData, setRankingData] = useState<RankingData[]>([]);
  const [loading, setLoading] = useState(true);
  const title = searchParams.get('title');

  useEffect(() => {
    const fetchData = async () => {
      try {
        // 漫画詳細の取得
        // const detailResponse = await fetch('/mangaDetails.json');
        //const detailResponse = await fetch('/jumprank/mangaDetails.json');
        if (!title) return;
        const detailResponse = await fetch(`http://localhost:8080/work/${encodeURIComponent(title)}`);
        const detailData = await detailResponse.json();
        console.log(detailData.find((m: MangaDetail) => m.title === title));
        let manga = detailData.manga.find((m: MangaDetail) => m.title === title);

        if (manga) {
            // タイトルが存在することを確認
            if (!title) {
              console.error('Title is empty or null');
              return;
            }

            // NDLから単行本情報を取得
            {/*try {
              const volumes = await fetchNDLData(title, manga);

              if (volumes && volumes.length > 0) {
                manga = {
                  ...manga,
                  volumes: volumes
                };
              } else {
                console.warn('No volumes found for:', title);
              }
            } catch (error) {
              console.error('Error fetching NDL data:', error);
            }*/}
        }

        setMangaDetail(manga || null);

        // ランキングデータの取得
        //const rankingResponse = await fetch('/past-ranking-data.csv');
        const rankingResponse = await fetch('/jumprank/past-ranking-data.csv');
        const rankingText = await rankingResponse.text();
        const parsed = Papa.parse(rankingText, {
          header: true,
          skipEmptyLines: true,
          dynamicTyping: true,
        });
        setRankingData(parsed.data as RankingData[]);
      } catch (error) {
        console.error('Error fetching data:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, [title]);

  if (loading) {
    return (
      <Container>
        <Typography>Loading...</Typography>
      </Container>
    );
  }

  if (!mangaDetail) {
    return (
      <Container>
        <Typography color="error">漫画が見つかりませんでした。</Typography>
      </Container>
    );
  }

  return (
    <>
      <DetailHeaderNavi />
      <Container>
        <Box sx={{ py: 4 }}>
          {/* 基本情報 */}
          <Paper elevation={0} sx={{ p: 3, mb: 4, backgroundColor: '#f8f9fa', borderRadius: 2 }}>
            <Typography variant="h4" component="h1" gutterBottom sx={{ fontWeight: 'bold' }}>
              {mangaDetail.title}
            </Typography>
            <Box sx={{ mb: 2 }}>
              {mangaDetail.genres.map((genre) => (
                <Chip
                  key={genre}
                  label={genre}
                  sx={{ mr: 1, mb: 1, backgroundColor: '#009879', color: 'white' }}
                />
              ))}
            </Box>
            <Grid container spacing={2} sx={{ mt: 2 }}>
                <Typography variant="body1" sx={{ mb: 1 }}>
                  <strong>作者：</strong> {mangaDetail.author}
                </Typography>
                <Typography variant="body1" sx={{ mb: 1 }}>
                  <strong>出版社：</strong> {mangaDetail.publisher}
                </Typography>
                <Typography variant="body1" sx={{ mb: 1 }}>
                  <strong>掲載誌：</strong> {mangaDetail.magazine}
                </Typography>
                <Typography variant="body1" sx={{ mb: 1 }}>
                  <strong>ジャンル：</strong> {mangaDetail.demographic}
                </Typography>
                <Typography variant="body1">
                  <strong>連載開始：</strong>{new Date(mangaDetail.startDate).toLocaleDateString('ja-JP')}
                </Typography>
            </Grid>
          </Paper>

          {/* ランキング順位表 */}
          <Paper elevation={0} sx={{ p: 3, mt: 4, backgroundColor: '#f8f9fa', borderRadius: 2 }}>
            <style>
              {`
                .styled-table {
                  border-collapse: collapse;
                  margin: 20px 0;
                  font-size: 16px;
                  min-width: 400px;
                  box-shadow: 0 0 10px rgba(0,0,0,0.08);
                }
                .styled-table thead tr {
                  background-color: #009879;
                  color: #ffffff;
                  text-align: left;
                }
                .styled-table th,
                .styled-table td {
                  padding: 12px 15px;
                  border: 1px solid #dddddd;
                }
                .styled-table tbody tr {
                  border-bottom: 1px solid #dddddd;
                  background-color: #f3f3f3;
                }
                .styled-table tbody tr:nth-of-type(even) {
                  background-color: #e9f7f6;
                }
                .styled-table tbody tr:hover {
                  background-color: #b7eadc;
                  cursor: pointer;
                }
              `}
            </style>

            <Typography variant="h5" component="h2" gutterBottom sx={{ mb: 3, fontWeight: 'bold' }}>
              掲載順位一覧
            </Typography>
            <Box sx={{ overflowX: 'auto' }}>
              <table className="styled-table" style={{ width: '100%', borderCollapse: 'collapse' }}>
                <thead>
                  <tr>
                    <th style={{ 
                      backgroundColor: '#009879',
                      color: 'white',
                      padding: '12px',
                      textAlign: 'left',
                      borderBottom: '2px solid #dddddd'
                    }}>
                      号数
                    </th>
                    <th style={{ 
                      backgroundColor: '#009879',
                      color: 'white',
                      padding: '12px',
                      textAlign: 'left',
                      borderBottom: '2px solid #dddddd'
                    }}>
                      順位
                    </th>
                  </tr>
                </thead>
                <tbody>
                  {rankingData
                    .map((data, index) => ({
                      title: data.title,
                      rank: data[title || ""] as number
                    }))
                    .filter(item => item.rank !== undefined)
                    .map((item, index) => (
                      <tr key={item.title} style={{
                        backgroundColor: index % 2 === 0 ? '#f3f3f3' : '#ffffff',
                        borderBottom: '1px solid #dddddd',
                        transition: 'background-color 0.3s'
                      }}>
                        <td style={{ padding: '12px' }}>{item.title}</td>
                        <td style={{ padding: '12px' }}>{item.rank}位</td>
                      </tr>
                    ))}
                </tbody>
              </table>
            </Box>
          </Paper>

          {/* ランキング推移グラフ */}
          <Paper elevation={0} sx={{ p: 3, mt: 4, backgroundColor: '#f8f9fa', borderRadius: 2 }}>
            <Typography variant="h5" component="h2" gutterBottom sx={{ mb: 3, fontWeight: 'bold' }}>
              掲載順位の推移
            </Typography>
            <Box sx={{ width: '100%', height: 400 }}>
              <ResponsiveContainer>
                <LineChart
                  //data={rankingData}
                  data={[...rankingData].reverse()} //
                  margin={{
                    top: 20,
                    right: 30,
                    left: 20,
                    bottom: 5,
                  }}
                >
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis dataKey="title" />
                  <YAxis reversed />
                  <Tooltip />
                  <Legend />
                  <Line
                    type="monotone"
                    dataKey={title || ""}
                    stroke="#009879"
                    dot={{ stroke: '#009879', strokeWidth: 2, r: 4 }}
                    activeDot={{ r: 8 }}
                  />
                </LineChart>
              </ResponsiveContainer>
            </Box>
          </Paper>

            {/* 単行本リスト */}
          <Typography variant="h5" component="h2" gutterBottom sx={{ mt:3 , mb: 3, fontWeight: 'bold' }}>
            最新単行本
          </Typography>
          <Grid container spacing={3}>
            {mangaDetail.volumes.map((volume) => (
                <Card sx={{ 
                  height: '100%',
                  display: 'flex',
                  flexDirection: 'column',
                  transition: 'transform 0.3s ease-in-out',
                  '&:hover': {
                    transform: 'translateY(-8px)'
                  }
                }}>
                  <CardMedia
                    component="img"
                    sx={{ 
                      height: 300,
                      objectFit: 'contain',
                      bgcolor: '#f5f5f5'
                    }}
                    image={volume.coverImage || "/default-cover.jpg"}
                    alt={`第${volume.volume}巻カバー`}
                  />
                  <CardContent>
                    <Typography variant="h6" gutterBottom>
                      第{volume.volume}巻
                    </Typography>
                    <Typography variant="body2" color="text.secondary" paragraph>
                      {volume.description}
                    </Typography>
                    <Divider sx={{ my: 1 }} />
                    <Typography variant="body2" color="text.secondary">
                      発売日: {new Date(volume.releaseDate).toLocaleDateString('ja-JP')}
                    </Typography>
                    <Typography variant="body2" color="text.secondary">
                      価格: ¥{volume.price.toLocaleString()}
                    </Typography>
                    <Typography variant="body2" color="text.secondary">
                      ページ数: {volume.pages}ページ
                    </Typography>
                  </CardContent>
                </Card>
            ))}
          </Grid>

        </Box>
      </Container>
      <Footer/>
    </>
  );
}
export default DetailPage;
